      if (field === "valueTotal") {
        updatedPurchase[field] = removeCurrencyMask(value);
      } else if (field === "data") {
        updatedPurchase[field] = convertDate(value);
      } else {
        updatedPurchase[field] = value;
      }
      return [...prevState];
    });
  };

  const deletePurchase = async (id) => {
    try {
      await api.delete(`/compras/${id}`);
      setRefresh(!refresh);
    } catch (error) {
      console.error(error);
    }
  };

  const archivePurchase = async (id) => {
    try {
      await api.put(`/compras/${id}/archived`, { archived: true });
      setRefresh(!refresh);
      alert("Compra arquivada com sucesso!");
    } catch (error) {
      console.error("Erro ao arquivar compra:", error);
      alert("Falha ao arquivar a compra.");
    }
  };

  const updateTrackingStatus = (purchaseId, status) => {
    setTrackingStatus(prevState => ({
      ...prevState,
      [purchaseId]: status
    }));
  };

  function removeCurrencyMask(value) {
    return value.replace(/\s|R\$/g, "").replace(",", ".");
  }

  function convertDate(dateString) {
    const parts = dateString.split('/');
    const day = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10);
    const year = parseInt(parts[2], 10);
    return new Date(year, month - 1, day);
  }

  return (
    <>
      <Form setList={handleListUpdate} />
      {loading ? (
        <p>Carregando...</p>
      ) : (
        <>
          <table>
            <thead>
              <tr>
                <th>Data Compra</th>
                <th>Produto</th>
                <th>Quantidade</th>
                <th>Valor Total</th>
                <th>Loja de Compra</th>
                <th>Código da Compra</th>
                <th>Forma de Pagamento</th>
                <th>Código de rastreio</th>
                <th>Status Encomenda</th>
                <th>  </th>
              </tr>
            </thead>
            <tbody>{displayPurchases}</tbody>
            <tbody>{displayTotal}</tbody>
          </table>
          <ReactPaginate
            previousLabel={<FaChevronLeft />}
            nextLabel={<FaChevronRight />}
            pageCount={pageCount}
            onPageChange={changePage}
            containerClassName={"paginationButtons"}
            previousLinkClassName={"previousButton"}
            nextLinkClassName={"nextButton"}
            disabledClassName={"paginationDisabled"}
            activeClassName={"paginationActive"}
          />
        </>
      )}
    </>
  );
};

export default List;
```

